package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.JsonNode;import com.hmdp.ai.domain.artifact.*;import com.hmdp.ai.domain.run.*;import java.util.*;
public final class NodeExecutionResult {private final NodeRunStatus status;private final JsonNode output;private final List<String>nextNodeIds;private final Map<String,Object>variableUpdates;private final List<ArtifactReference>artifacts;private final List<Citation>citations;private final List<String>warnings;private final UsageSummary usage;private final boolean retryable;private final String errorCode;public NodeExecutionResult(NodeRunStatus status,JsonNode output,List<String>next,Map<String,Object>updates,List<ArtifactReference>artifacts,List<Citation>citations,List<String>warnings,UsageSummary usage,boolean retryable,String errorCode){this.status=status;this.output=output;this.nextNodeIds=immutable(next);this.variableUpdates=Collections.unmodifiableMap(new LinkedHashMap<>(updates==null?Collections.emptyMap():updates));this.artifacts=immutable(artifacts);this.citations=immutable(citations);this.warnings=immutable(warnings);this.usage=usage;this.retryable=retryable;this.errorCode=errorCode;}private static<T>List<T>immutable(List<T>x){return Collections.unmodifiableList(new ArrayList<>(x==null?Collections.emptyList():x));}public static NodeExecutionResult success(JsonNode out,List<String>next,Map<String,Object>updates){return new NodeExecutionResult(NodeRunStatus.SUCCEEDED,out,next,updates,null,null,null,UsageSummary.empty(0),false,null);}public static NodeExecutionResult failure(String code,boolean retry){return new NodeExecutionResult(NodeRunStatus.FAILED,null,null,null,null,null,null,UsageSummary.empty(0),retry,code);}public NodeRunStatus getStatus(){return status;}public JsonNode getOutput(){return output;}public List<String>getNextNodeIds(){return nextNodeIds;}public Map<String,Object>getVariableUpdates(){return variableUpdates;}public List<ArtifactReference>getArtifacts(){return artifacts;}public List<Citation>getCitations(){return citations;}public List<String>getWarnings(){return warnings;}public UsageSummary getUsage(){return usage;}public boolean isRetryable(){return retryable;}public String getErrorCode(){return errorCode;}}
